INSERT INTO corpus_document VALUES ('e60c72da-968b-44e9-b4d8-926fce7197cb', 'DMS-00000260_KR-017_v1.1_de.pdf', 'application/pdf', '45859', 'other', 'manual', 'Manual upload', '2026-11-09 17:10:22.169161', '

