INSERT INTO corpus_document VALUES ('4888f625-7024-424b-9064-4ca1bd20e837', 'DMS-00000299_RE00015_zh_v1.0.txt', 'text/plain', '2338', 'other', 'manual', 'Manual upload', '2026-11-09 17:11:02.849413', '环境、健康与安全：中国补充规定（安全生产法）
