INSERT INTO corpus_document VALUES ('f537ee00-ad12-4506-b7d3-0e4aa487d637', 'DMS-00000486_SDB-11249-DE_de_v3.1.pdf', 'application/pdf', '47630', 'other', 'manual', 'Manual upload', '2026-11-09 17:14:27.020512', '

