INSERT INTO corpus_document VALUES ('ddfb8e2a-756f-4aba-927d-55ea21df1b8d', 'DMS-00000545_KR-003_v2.0_en.pdf', 'application/pdf', '45032', 'other', 'manual', 'Manual upload', '2026-11-09 17:15:37.33312', '

Business Partner Due Diligence Policy
Konzernrichtlinie
