INSERT INTO corpus_document VALUES ('0d258b59-3cd2-4bca-86ae-26baff34a170', 'DMS-00000570_CRM-20250117-0003.txt', 'text/plain', '897', 'other', 'manual', 'Manual upload', '2026-11-09 17:16:04.116854', 'From: william.hughes@marenthal-chemicals.com
