INSERT INTO corpus_document VALUES ('ddac960a-ada9-423c-89cc-dbd5abc15a7d', 'DMS-00000571_SDB-11198-FR_fr_v9.0.pdf', 'application/pdf', '47159', 'other', 'manual', 'Manual upload', '2026-11-09 17:16:05.010304', '

Fiche de données de sécurité Pentaérythritol, qualité
technique
