INSERT INTO corpus_document VALUES ('aba3abb7-918d-47da-b87f-f383eb33b6a1', 'DMS-00000698_KR-017_v2.0_en.pdf', 'application/pdf', '45900', 'other', 'manual', 'Manual upload', '2026-11-09 17:18:06.259131', '

Emergency and Crisis Management
Konzernrichtlinie
