INSERT INTO corpus_document VALUES ('f86fdd59-1791-42c8-a26d-3c2d799790e1', 'DMS-00000722_CRM-20250328-0025.txt', 'text/plain', '736', 'other', 'manual', 'Manual upload', '2026-11-09 17:18:34.007548', 'From: linmei.sun@marenthal-chemicals.cn
To: y.han@antai-coatings.cn
