INSERT INTO corpus_document VALUES ('9212cf77-dcaf-457f-ae6a-4c7197d90f3d', 'DMS-00000849_CRM-20250520-0046.txt', 'text/plain', '812', 'other', 'manual', 'Manual upload', '2026-11-09 17:20:27.872275', 'From: patrick.hein@marenthal-chemie.de
