INSERT INTO corpus_document VALUES ('6d57c249-ff4f-4a7b-8e65-c378e5e26882', 'DMS-00000968_SDB-11182-DE_de_v4.1.pdf', 'application/pdf', '47534', 'other', 'manual', 'Manual upload', '2026-11-09 17:22:28.004223', '

