INSERT INTO corpus_document VALUES ('7c658cc2-a583-4f0f-9c10-6c4e46006884', 'DMS-00000981_CRM-20250716-0064.txt', 'text/plain', '777', 'other', 'manual', 'Manual upload', '2026-11-09 17:22:38.008032', 'From: steven.collins@marenthal.fr
