INSERT INTO corpus_document VALUES ('1c100aab-ec5e-4232-bccd-8d32df2ba72c', 'DMS-00001026_CRM-20250804-0069.txt', 'text/plain', '867', 'other', 'manual', 'Manual upload', '2026-11-09 17:23:10.880726', 'From: patrick.hein@marenthal-chemie.de
