INSERT INTO corpus_document VALUES ('b3dec1b0-6f5b-4f41-8c01-78544e4d6a52', 'DMS-00001163_CRM-20250916-0091.txt', 'text/plain', '801', 'other', 'manual', 'Manual upload', '2026-11-09 17:25:45.843786', 'From: marine.leroy@marenthal.fr
