INSERT INTO corpus_document VALUES ('a16c3304-adc9-402e-8204-a5e919bcb414', 'DMS-00001212_SDB-10977-CN_zh_v9.1.txt', 'text/plain', '2249', 'other', 'manual', 'Manual upload', '2026-11-09 17:26:32.962084', '安全技术说明书 Marencoat PH 1102 环氧固化剂（B组分）
Sicherheitsdatenblatt

文件编号: DMS-00001212
版本: 9.1
生效日期: 2025-10-17
公司: Marenthal Chemicals (Shanghai) Co., Ltd.
状态: Approved
