INSERT INTO corpus_document VALUES ('364235cb-39cc-41c5-9596-11f38064a8dc', 'DMS-00001252_CRM-20251015-0110.txt', 'text/plain', '819', 'other', 'manual', 'Manual upload', '2026-11-09 17:27:21.962233', 'From: christiane.kremer@marenthal-chemie.de
