INSERT INTO corpus_document VALUES ('392dc308-dae0-4f36-b117-1b472c2a9c28', 'DMS-00001256_CRM-20251016-0111.txt', 'text/plain', '831', 'other', 'manual', 'Manual upload', '2026-11-09 17:27:25.650457', 'From: lukas.schmidt@marenthal-chemie.de
