INSERT INTO twin_question VALUES ('c84a4329-3fe9-4bc4-b56d-cdeda5e9fae8', '101', 'What is the company''s full legal name and legal form?', 'identity', NULL, 'open', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Wie lautet der vollständige rechtliche Name des Unternehmens und seine Rechtsform?"}}');
INSERT INTO twin_question VALUES ('d0e979d3-9b5f-429d-95a3-2574945fa189', '102', 'Where is the company''s registered seat, and in which commercial register is it recorded?', 'identity', NULL, 'open', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Wo ist der eingetragene Sitz des Unternehmens und in welchem Handelsregister ist es erfasst?"}}');
INSERT INTO twin_question VALUES ('4b08d3aa-3e36-40d2-a07e-f178919739f7', '103', 'What is the company''s core business in one or two sentences?', 'identity', NULL, 'open', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Was ist das Kerngeschäft des Unternehmens in ein bis zwei Sätzen?"}}');
INSERT INTO twin_question VALUES ('f3703834-70af-4d4a-b3ca-0d8e0f079fc8', '104', 'Which industry classifications (e.g. NACE/WZ codes) apply to the company''s activities?', 'identity', NULL, 'open', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Welche Branchenklassifikationen (z. B. NACE-/WZ-Codes) treffen auf die Tätigkeiten des Unternehmens zu?"}}');
INSERT INTO twin_question VALUES ('2447f780-deb0-480d-b7ae-d17b972f1d0b', '105', 'Is the company part of a group? If so, who is the ultimate parent and where is it seated?', 'identity', NULL, 'open', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Ist das Unternehmen Teil eines Konzerns? Falls ja, wer ist die oberste Muttergesellschaft und wo hat sie ihren Sitz?"}}');
INSERT INTO twin_question VALUES ('c996c985-1156-4757-b292-79f381f52598', '106', 'How many employees does the company have, and how has that number changed over the last three years?', 'identity', NULL, 'open', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Wie viele Mitarbeitende hat das Unternehmen und wie hat sich diese Zahl in den letzten drei Jahren verändert?"}}');
INSERT INTO twin_question VALUES ('db1368c9-44aa-4a5d-9c34-51d7cfbd9df9', '107', 'What was the company''s revenue in the last completed financial year?', 'identity', NULL, 'open', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Wie hoch war der Umsatz des Unternehmens im letzten abgeschlossenen Geschäftsjahr?"}}');
INSERT INTO twin_question VALUES ('bba94902-8d11-4131-b970-4ffc4880dccc', '108', 'What was the company''s balance sheet total in the last completed financial year?', 'identity', NULL, 'open', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Wie hoch war die Bilanzsumme des Unternehmens im letzten abgeschlossenen Geschäftsjahr?"}}');
INSERT INTO twin_question VALUES ('e49360ea-7560-4ebe-bc0e-155b1ae7d839', '109', 'Is the company listed on a stock exchange or does it have publicly traded securities (shares or bonds)?', 'identity', NULL, 'boolean', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Ist das Unternehmen börsennotiert oder hat es öffentlich gehandelte Wertpapiere (Aktien oder Anleihen)?"}}');
INSERT INTO twin_question VALUES ('2f061309-afb5-41bb-a120-798dd1d9d7b1', '110', 'Who are the members of the management body, and how are responsibilities divided among them?', 'identity', NULL, 'open', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Wer sind die Mitglieder der Geschäftsleitung und wie sind die Zuständigkeiten unter ihnen verteilt?"}}');
INSERT INTO twin_question VALUES ('15a5b828-ffba-4c61-a8a8-9ee5c81d3736', '111', 'Does the company have a supervisory board or advisory board, and what decisions require its approval?', 'identity', NULL, 'open', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Hat das Unternehmen einen Aufsichtsrat oder Beirat und welche Entscheidungen bedürfen seiner Zustimmung?"}}');
INSERT INTO twin_question VALUES ('bc4a7db6-b855-4e7a-a6fb-bac27707133d', '112', 'Who holds more than 25% of the company''s shares or voting rights (beneficial owners)?', 'identity', NULL, 'open', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Wer hält mehr als 25 % der Anteile oder Stimmrechte des Unternehmens (wirtschaftlich Berechtigte)?"}}');
INSERT INTO twin_question VALUES ('b44c5953-d705-4956-a495-d72d870274d8', '113', 'Which financial year does the company use, and who audits its annual accounts?', 'identity', NULL, 'open', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Welches Geschäftsjahr verwendet das Unternehmen und wer prüft seinen Jahresabschluss?"}}');
