INSERT INTO twin_question VALUES ('562c5b38-3c10-4469-8841-6c3813a946e2', '115', 'In which countries does the company have legal entities, branches or permanent establishments?', 'footprint', NULL, 'open', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"In welchen Ländern hat das Unternehmen Gesellschaften, Niederlassungen oder Betriebsstätten?"}}');
INSERT INTO twin_question VALUES ('ef3cdb02-2d6c-403b-b511-44beb11846bc', '116', 'In which countries does the company sell products or services without a local entity?', 'footprint', NULL, 'open', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"In welchen Ländern verkauft das Unternehmen Produkte oder Dienstleistungen ohne eigene Gesellschaft vor Ort?"}}');
INSERT INTO twin_question VALUES ('d014b7f6-d08e-43da-9e21-fc31c9f5cfc1', '117', 'What share of revenue comes from outside the EU, and which non-EU markets matter most?', 'footprint', NULL, 'open', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Welcher Umsatzanteil stammt von außerhalb der EU und welche Nicht-EU-Märkte sind am wichtigsten?"}}');
INSERT INTO twin_question VALUES ('cfda1fac-a5dd-48a8-87e1-97390038533d', '118', 'Does the company have production sites, and where are they located?', 'footprint', NULL, 'open', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Hat das Unternehmen Produktionsstandorte und wo befinden sie sich?"}}');
