INSERT INTO twin_question VALUES ('55f24c08-e72a-43d2-8123-7df84ae13b15', '121', 'Does the company do business with or in countries under EU, US or UN sanctions?', 'footprint', NULL, 'boolean', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Macht das Unternehmen Geschäfte mit oder in Ländern, die EU-, US- oder UN-Sanktionen unterliegen?"}}');
