INSERT INTO twin_question VALUES ('e34a362b-47c8-4d6c-888e-571991a288ca', '123', 'Are there plans to enter new markets or open new locations in the next two years?', 'footprint', NULL, 'boolean', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Gibt es Pläne, in den nächsten zwei Jahren neue Märkte zu erschließen oder neue Standorte zu eröffnen?"}}');
INSERT INTO twin_question VALUES ('87d6cf3a-ed87-46e0-883a-767c22b2ea51', '124', 'Does the company sell to consumers, to businesses, or to public bodies, and in what proportion?', 'footprint', NULL, 'open', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Verkauft das Unternehmen an Verbraucher, an Unternehmen oder an öffentliche Stellen, und in welchem Verhältnis?"}}');
INSERT INTO twin_question VALUES ('9b3e508f-f9fc-4a05-baf7-d54554a6bb5b', '125', 'Which of the company''s activities require a licence, permit or registration, and who granted it?', 'licences', NULL, 'open', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Welche Tätigkeiten des Unternehmens erfordern eine Lizenz, Erlaubnis oder Registrierung und wer hat sie erteilt?"}}');
INSERT INTO twin_question VALUES ('f0de049d-2e9e-4a82-a674-6bfec1396d64', '126', 'Which supervisory authorities oversee the company, and for what?', 'licences', NULL, 'open', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Welche Aufsichtsbehörden beaufsichtigen das Unternehmen und wofür?"}}');
INSERT INTO twin_question VALUES ('d88f1fb2-f9a6-44ee-8093-aefdb662965c', '127', 'Are any licences or permits due for renewal in the next 24 months?', 'licences', NULL, 'boolean', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Stehen in den nächsten 24 Monaten Verlängerungen von Lizenzen oder Genehmigungen an?"}}');
INSERT INTO twin_question VALUES ('33999415-198e-48e1-8390-29f39337bfa5', '128', 'Has the company ever had a licence refused, restricted, suspended or withdrawn?', 'licences', NULL, 'boolean', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Wurde dem Unternehmen jemals eine Lizenz verweigert, eingeschränkt, ausgesetzt oder entzogen?"}}');
INSERT INTO twin_question VALUES ('cba0dd74-714c-4744-abb6-cd5ba123a851', '129', 'Does the company passport or notify any licence into other EU member states?', 'licences', NULL, 'boolean', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Nutzt das Unternehmen für eine Erlaubnis das EU-Passporting oder Notifizierungen in andere Mitgliedstaaten?"}}');
INSERT INTO twin_question VALUES ('4d9b1fee-9907-4157-aec2-7bd2d8f402e2', '130', 'Which professional or industry-body memberships carry binding rules for the company?', 'licences', NULL, 'open', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Welche Mitgliedschaften in Berufs- oder Branchenverbänden sind für das Unternehmen mit verbindlichen Regeln verbunden?"}}');
INSERT INTO twin_question VALUES ('0cb88ab5-6232-416c-8d7f-db45216308ae', '131', 'Which regular reports must the company file with authorities, and at what frequency?', 'licences', NULL, 'open', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Welche regelmäßigen Meldungen muss das Unternehmen bei Behörden einreichen und in welchem Turnus?"}}');
INSERT INTO twin_question VALUES ('1b014406-e6af-4e71-ae88-ff6b44c967e2', '132', 'Is any activity conducted under an exemption or grandfathering rule rather than a full licence?', 'licences', NULL, 'open', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Wird eine Tätigkeit auf Grundlage einer Ausnahme oder Bestandsschutzregelung statt einer vollen Erlaubnis ausgeübt?"}}');
INSERT INTO twin_question VALUES ('47533bed-aa7f-4820-9fd6-0686c1eb691c', '133', 'What are the company''s main products or services, by revenue?', 'products', NULL, 'open', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Was sind die wichtigsten Produkte oder Dienstleistungen des Unternehmens, gemessen am Umsatz?"}}');
INSERT INTO twin_question VALUES ('ef56b246-cdc5-4340-8feb-ef4ff9ebe470', '134', 'Do any products fall under CE marking or other conformity assessment regimes? If so, which ones?', 'products', NULL, 'open', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Fallen Produkte unter die CE-Kennzeichnung oder andere Konformitätsbewertungsverfahren? Falls ja, welche?"}}');
INSERT INTO twin_question VALUES ('7255ec28-dd8e-4065-9127-94a5d9e933b8', '135', 'Do any products contain substances subject to REACH, RoHS or similar chemical regulations?', 'products', NULL, 'open', 'catalogue', 'open', NULL, NULL, NULL, '{"de":{"text":"Enthalten Produkte Stoffe, die REACH, RoHS oder ähnlichen Chemikalienvorschriften unterliegen?"}}');
